def transform_demo_rule(grid):
    """
    Rule discovered:
    1. 8 -> 2 if in a horizontal 8-block bounded by 4s (left and right of block are 4)
    2. OR 8 -> 2 if in a vertical 8-block bounded by 4s (above and below of block are 4)
    3. 4 -> 2 if 4 above in same column (continuing a 4-run)
    """
    result = [row[:] for row in grid]

    # Row 1: Find horizontal 8-blocks bounded by 4s
    for r in range(rows):
        row = grid[r]
        i = 0
        while i < len(row):
            if row[i] == 8:
                start = i
                in_block = True
                while i < len(row) and row[i] == 8:
                    i += 1
                end = i  # end is first index that is NOT 8

                # Check if bounded by 4s
                left_bounded = (start > 0 and row[start-1] == 4)
                right_bounded = (end < len(row) and row[end] == 4)

                if left_bounded and right_bounded:
                    # All 8s in [start, end) become 2
                    for c in range(start, end):
                        result[r][c] = 2
            i += 1 if in_block else 1

    # Col-wise blocks (for vertical sandwich)
    for c in range(cols):
        col = [grid[r][c] for r in range(rows)]
        r_idx = 0
        while r_idx < len(col):
            if col[r_idx] == 8:
                start = r_idx
                in_block = True
                while r_idx < len(col) and col[r_idx] == 8:
                    r_idx += 1
                end = r_idx

                left_bounded = (start > 0 and col[start-1] == 4)
                right_bounded = (end < len(col) and col[end] == 4)

                if left_bounded and right_bounded:
                    # All 8s in column c between start and end become 2
                    for r2 in range(start, end):
                        result[r2][c] = 2
            r_idx += 1 if in_block else 1

    # 4 becomes 2 if 4 immediately above
    for r in range(1, rows):
        for c in range(cols):
            if result[r][c] == 4:
                if grid[r-1][c] == 4:
                    result[r][c] = 2

    return result

